package faa_autopilot_engagement.FAA_Autopilot_Engagement

import org.sireum._
import art._
import faa_autopilot_engagement._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Status_Reporting_Thread_Api {
  def id: Art.BridgeId
  def status_in_Id : Art.PortId
  def status_out_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var status_out: FAA_Autopilot_Engagement.AP_Status.Type = $

  def put_status_out(value : FAA_Autopilot_Engagement.AP_Status.Type) : Unit = {
    Contract(
      Modifies(status_out),
      Ensures(
        status_out == value
      )
    )
    Spec {
      status_out = value
    }

    Art.putValue(status_out_Id, FAA_Autopilot_Engagement.AP_Status_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Status_Reporting_Thread_Initialization_Api (
  val id: Art.BridgeId,
  val status_in_Id : Art.PortId,
  val status_out_Id : Art.PortId) extends Status_Reporting_Thread_Api

@datatype class Status_Reporting_Thread_Operational_Api (
  val id: Art.BridgeId,
  val status_in_Id : Art.PortId,
  val status_out_Id : Art.PortId) extends Status_Reporting_Thread_Api {

  // Logika spec var representing port state for incoming data port
  @spec var status_in: FAA_Autopilot_Engagement.AP_Status.Type = $

  def get_status_in() : Option[FAA_Autopilot_Engagement.AP_Status.Type] = {
    Contract(
      Ensures(
        Res == Some(status_in)
      )
    )
    val value : Option[FAA_Autopilot_Engagement.AP_Status.Type] = Art.getValue(status_in_Id) match {
      case Some(FAA_Autopilot_Engagement.AP_Status_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port status_in.  Expecting 'FAA_Autopilot_Engagement.AP_Status_Payload' but received ${v}")
        None[FAA_Autopilot_Engagement.AP_Status.Type]()
      case _ => None[FAA_Autopilot_Engagement.AP_Status.Type]()
    }
    return value
  }
}
